System.Collections.IEnumerator Run(){var maps=UnityEngine.Object.FindObjectsOfType<UnityEngine.Tilemaps.Tilemap>();var bodies=new System.Collections.Generic.List<UnityEngine.GameObject>();var expected=new System.Collections.Generic.List<float>();var lines=new System.Collections.Generic.List<string>();try{foreach(var map in maps){var candidates=new System.Collections.Generic.List<UnityEngine.Vector3Int>();foreach(var c in map.cellBounds.allPositionsWithin)if(map.HasTile(c)&&Enumerable.Range(1,3).All(y=>!map.HasTile(c+new UnityEngine.Vector3Int(0,y,0))&&!map.HasTile(c+new UnityEngine.Vector3Int(-1,y,0))&&!map.HasTile(c+new UnityEngine.Vector3Int(1,y,0))))candidates.Add(c);var cell=candidates.OrderBy(c=>c.y).ThenBy(c=>System.Math.Abs(c.x)).First();var center=map.GetCellCenterWorld(cell);var body=new UnityEngine.GameObject(map.transform.parent.name+" probe");body.layer=7;body.transform.position=center+new UnityEngine.Vector3(0,1.6f,0);body.AddComponent<UnityEngine.CircleCollider2D>().radius=.15f;body.AddComponent<UnityEngine.Rigidbody2D>();bodies.Add(body);expected.Add(center.y+.55f);}
yield return new UnityEngine.WaitForSeconds(2f);
for(int i=0;i<bodies.Count;i++){if(UnityEngine.Mathf.Abs(bodies[i].transform.position.y-expected[i])>.035f)throw new System.Exception("Drop failed "+bodies[i].name+" at "+bodies[i].transform.position+" expected="+expected[i]);lines.Add(bodies[i].name+" falling-body PASS");}
foreach(var map in maps){var tile=map.GetTilesBlock(map.cellBounds).First(t=>t!=null);var cell=new UnityEngine.Vector3Int(500,500,0);map.SetTile(cell,tile);yield return new UnityEngine.WaitForSeconds(.1f);UnityEngine.Collider2D collider=map.GetComponent<UnityEngine.CompositeCollider2D>();if(collider==null)collider=map.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();if(!collider.OverlapPoint(map.GetCellCenterWorld(cell)))throw new System.Exception("Paint failed "+map.name);var first=map.GetSprite(cell);map.SetTile(cell+UnityEngine.Vector3Int.up,tile);yield return null;if(first==map.GetSprite(cell))throw new System.Exception("Neighbor edge refresh failed");map.SetTile(cell,null);map.SetTile(cell+UnityEngine.Vector3Int.up,null);yield return new UnityEngine.WaitForSeconds(.1f);if(collider.OverlapPoint(map.GetCellCenterWorld(cell)))throw new System.Exception("Erase failed");lines.Add(map.transform.parent.name+" paint/erase collision and RuleTile neighbor refresh PASS");}System.IO.File.WriteAllLines("scripts/tilemap-grid-20261110/play-tests.txt",lines);}finally{foreach(var body in bodies)UnityEngine.Object.Destroy(body);}}return Run();
